import { useState } from "react";

export function App() {
  const [status, setStatus] = useState("idle");
  return (
    <div>
      <button data-testid="empty-onclick" onClick={() => setStatus("fixed")}>Empty onClick</button>
      <span data-testid="status">{status}</span>
    </div>
  );
}
